SELECT DISTINCTROW qryRemembraningAktMem.[Element Nr], qryRemembraningAktMem.Elektrolyseur, qryRemembraningAktMem.Position, qryRemembraningAktMem.[Anoden Nr], qryRemembraningAktMem.[Kathoden Nr], qryRemembraningAktMem.[Membran Nr], qryRemembraningAktMem.Membrantyp, qryRemembraningAktMem.Gruppe, qryRemembraningAktMem.[Einschalt Datum], qryRemembraningAktMem.[Ausschalt Datum], qryRemembraningAktMem.GesamtDOL, qryRemembraningAktMem.AktuelleDOL, qryRemembraningAktMem.Abschaltgrund, qryRemembraningAktMem.[Anode Coating], qryRemembraningAktMem.[Anode Electrode], qryRemembraningAktMem.[Anode Shell], qryRemembraningAktMem.[Cathode Coating], qryRemembraningAktMem.[Cathode Electrode], qryRemembraningAktMem.[Cathode Shell], qryRemembraningAktMem.[Info Membrane], qryRemembraningAktMem.Remarks, qryRemembraningAktMem.[Montage Datum], qryRemembraningAktMem.[Demontage Datum], qryRemembraningAktMem.[Elektroden Abstand], qryRemembraningDOL.ElementePassiv, qryRemembraningDOL.ElementeGesamt, qryRemembraningDOL.ElementeAktiv, qryRemembraningDOL.PassiveDOL, qryRemembraningDOL.AktiveDOL, qryRemembraningDOL.GesamtDOL, qryRemembraningDOL.[Membran Nr]
FROM tblGewDaten, qryRemembraningAktMem INNER JOIN qryRemembraningDOL ON qryRemembraningAktMem.[Membran Nr] = qryRemembraningDOL.[Membran Nr];
